```R
with_temp_install <- function(code, pkg = ".") {
  dev_lib <- file.path(tempdir(), "dev-library")
  
  if (!file.exists(dev_lib)) {
    dir.create(dev_lib)
  }

  if (needs_install(pkg)) {
